content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-border: #bfdbfe;
  --accent-color: #0d9488;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --bg-app: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-subtle: #f1f5f9;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-app);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* アプリ全体コンテナ */
.app-container {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  position: relative;
}

/* ヘッダー */
.header {
  text-align: center;
  margin-bottom: 28px;
}

.title {
  font-size: 1.85rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* メインレイアウト */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* 変換カード共通スタイル */
.converter-card,
.table-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-md);
}

/* 入力エリア */
.input-row {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 12px;
  margin-bottom: 20px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.number-input {
  width: 100%;
  padding: 12px 14px;
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--bg-card);
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.number-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.unit-select {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--bg-card);
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.unit-select:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

/* 単位入替ボタン */
.swap-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  width: 48px;
  min-width: 48px;
  border-radius: var(--radius-full);
  border: 1.5px solid var(--border-color);
  background-color: var(--bg-card);
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.swap-btn:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
  transform: rotate(180deg);
}

.swap-btn:active {
  transform: scale(0.95) rotate(180deg);
}

/* 結果表示エリア */
.result-display {
  background: linear-gradient(135deg, var(--primary-light), #f0fdf4);
  border: 1px solid var(--primary-border);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.result-main {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.result-value {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--primary-color);
  line-height: 1.1;
  word-break: break-all;
}

.result-unit {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-muted);
  white-space: nowrap;
}

.result-meta {
  font-size: 0.85rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--primary-border);
}

/* プリセットセクション */
.presets-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.presets-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}

.preset-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.preset-tag {
  background-color: var(--bg-card-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  padding: 8px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.preset-tag:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
}

.preset-tag:active {
  transform: scale(0.96);
}

/* コピーボタン */
.copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
  min-height: 34px;
  white-space: nowrap;
  user-select: none;
}

.copy-btn:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
}

.copy-btn:active {
  transform: scale(0.97);
}

/* 一括比較テーブル */
.table-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.table-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.table-container {
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  -webkit-overflow-scrolling: touch;
}

.conversion-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.table-th {
  background-color: var(--bg-card-subtle);
  color: var(--text-muted);
  font-weight: 600;
  font-size: 0.85rem;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}

.table-td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border-color);
  vertical-align: middle;
}

.conversion-table tbody tr:last-child .table-td {
  border-bottom: none;
}

.conversion-table tbody tr:hover {
  background-color: rgba(239, 246, 255, 0.4);
}

.table-unit-name {
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.table-unit-val {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text-main);
  font-size: 1.05rem;
  word-break: break-all;
}

.action-cell {
  text-align: right;
  width: 90px;
}

/* トースト通知 */
.copy-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background-color: #0f172a;
  color: #f8fafc;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 8px;
  animation: toastFade 0.25s ease-out;
  pointer-events: none;
}

@keyframes toastFade {
  from {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

/* 補足注釈 */
.info-note {
  font-size: 0.8rem;
  color: var(--text-light);
  line-height: 1.4;
  text-align: center;
  margin-top: 8px;
}

/* レスポンシブ対応 (モバイル向け 640px以下) */
@media (max-width: 640px) {
  .app-container {
    padding: 16px 12px 36px;
  }

  .title {
    font-size: 1.45rem;
  }

  .subtitle {
    font-size: 0.85rem;
  }

  .converter-card,
  .table-card {
    padding: 16px;
  }

  .input-row {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .swap-btn {
    align-self: center;
    transform: rotate(90deg);
    margin: 2px 0;
  }

  .swap-btn:hover {
    transform: rotate(270deg);
  }

  .swap-btn:active {
    transform: scale(0.95) rotate(270deg);
  }

  .result-value {
    font-size: 1.8rem;
  }

  .table-td,
  .table-th {
    padding: 10px 12px;
  }

  .table-unit-val {
    font-size: 0.95rem;
  }
}

/* 極小スマートフォン対応 (360px以下) */
@media (max-width: 360px) {
  .app-container {
    padding: 12px 8px 24px;
  }

  .number-input,
  .unit-select {
    padding: 10px 12px;
    font-size: 1rem;
  }

  .result-value {
    font-size: 1.5rem;
  }

  .preset-tag {
    padding: 6px 10px;
    font-size: 0.8rem;
    min-height: 34px;
  }
}

export type LengthUnitId = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'ft';

export interface LengthUnitItem {
  id: LengthUnitId;
  name: string;
  symbol: string;
  toBaseMeter: number;
  description: string;
}

export interface ConversionRow {
  unitId: LengthUnitId;
  name: string;
  symbol: string;
  formattedValue: string;
  rawValue: number;
}

export interface PresetItem {
  label: string;
  value: number;
  unitId: LengthUnitId;
}

export interface ConversionTableProps {
  rows: ConversionRow[];
  onCopy: (text: string, label: string) => void;
  copiedSymbol: string | null;
}

import { LengthUnitId, LengthUnitItem, ConversionRow } from '../types';

export const UNITS: Record<LengthUnitId, LengthUnitItem> = {
  mm: {
    id: 'mm',
    name: 'ミリメートル',
    symbol: 'mm',
    toBaseMeter: 0.001,
    description: '1mの1,000分の1'
  },
  cm: {
    id: 'cm',
    name: 'センチメートル',
    symbol: 'cm',
    toBaseMeter: 0.01,
    description: '1mの100分の1'
  },
  m: {
    id: 'm',
    name: 'メートル',
    symbol: 'm',
    toBaseMeter: 1,
    description: '国際標準の基本単位'
  },
  km: {
    id: 'km',
    name: 'キロメートル',
    symbol: 'km',
    toBaseMeter: 1000,
    description: '1,000メートル'
  },
  inch: {
    id: 'inch',
    name: 'インチ',
    symbol: 'in',
    toBaseMeter: 0.0254,
    description: '正確に25.4mm'
  },
  ft: {
    id: 'ft',
    name: 'フィート',
    symbol: 'ft',
    toBaseMeter: 0.3048,
    description: '12インチ (304.8mm)'
  }
};

export const UNIT_LIST: LengthUnitItem[] = [
  UNITS.mm,
  UNITS.cm,
  UNITS.m,
  UNITS.km,
  UNITS.inch,
  UNITS.ft
];

export const convertLength = (
  value: number,
  fromUnit: LengthUnitId,
  toUnit: LengthUnitId
): number => {
  if (isNaN(value) || !isFinite(value)) {
    return 0;
  }
  if (fromUnit === toUnit) {
    return value;
  }

  const fromFactor = UNITS[fromUnit]?.toBaseMeter ?? 1;
  const toFactor = UNITS[toUnit]?.toBaseMeter ?? 1;

  // 基本単位（メートル）に換算してから対象単位に換算
  const meterValue = value * fromFactor;
  return meterValue / toFactor;
};

export const formatNumber = (value: number): string => {
  if (isNaN(value) || !isFinite(value)) {
    return '0';
  }
  if (value === 0) {
    return '0';
  }

  const absVal = Math.abs(value);

  // 極端に小さい値または大きい値は指数表記
  if (absVal < 0.000001 || absVal >= 10000000000) {
    return value.toExponential(4).replace(/\.0+e/, 'e');
  }

  // 浮動小数点計算の丸め誤差を解消するために高精度でtoFixed
  const precision = 8;
  const fixed = Number(value.toFixed(precision));

  // ロケール形式で3桁カンマ区切りにしつつ小数点以下の末尾不要ゼロを除去
  const parts = fixed.toString().split('.');
  const integerPart = Number(parts[0]).toLocaleString('ja-JP');

  if (parts.length > 1 && parts[1]) {
    const decimalPart = parts[1].replace(/0+$/, '');
    if (decimalPart.length > 0) {
      return `${integerPart}.${decimalPart}`;
    }
  }

  return integerPart;
};

export const getAllConversions = (
  value: number,
  baseUnit: LengthUnitId
): ConversionRow[] => {
  return UNIT_LIST.map((unit) => {
    const converted = convertLength(value, baseUnit, unit.id);
    return {
      unitId: unit.id,
      name: unit.name,
      symbol: unit.symbol,
      formattedValue: formatNumber(converted),
      rawValue: converted
    };
  });
};

import { FC } from 'react';
import { Copy, Check, TableProperties } from 'lucide-react';
import { ConversionTableProps } from '../types';

const ConversionTable: FC<ConversionTableProps> = ({
  rows = [],
  onCopy,
  copiedSymbol
}) => {
  const handleCopy = (formattedValue: string, symbol: string) => {
    const textToCopy = `${formattedValue} ${symbol}`;
    onCopy?.(textToCopy, symbol);
  };

  return (
    <div className="table-card">
      <h2 className="table-title">
        <TableProperties size={20} aria-hidden="true" />
        全単位の一括換算一覧
      </h2>

      <div className="table-container">
        <table className="conversion-table">
          <thead>
            <tr>
              <th className="table-th">単位名</th>
              <th className="table-th">記号</th>
              <th className="table-th">換算値</th>
              <th className="table-th action-cell">コピー</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const isCopied = copiedSymbol === row.symbol;

              return (
                <tr key={row.unitId}>
                  <td className="table-td">
                    <span className="table-unit-name">{row.name}</span>
                  </td>
                  <td className="table-td">
                    <code>{row.symbol}</code>
                  </td>
                  <td className="table-td">
                    <span className="table-unit-val">{row.formattedValue}</span>
                  </td>
                  <td className="table-td action-cell">
                    <button
                      type="button"
                      className="copy-btn"
                      onClick={() => handleCopy(row.formattedValue, row.symbol)}
                      aria-label={`${row.name}の値をコピー`}
                    >
                      {isCopied ? (
                        <>
                          <Check size={14} color="#16a34a" aria-hidden="true" />
                          <span>済</span>
                        </>
                      ) : (
                        <>
                          <Copy size={14} aria-hidden="true" />
                          <span>コピー</span>
                        </>
                      )}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ConversionTable;

import { useState, useMemo, ChangeEvent } from 'react';
import { ArrowLeftRight, Copy, Check, Sparkles, Ruler } from 'lucide-react';
import { LengthUnitId, PresetItem } from './types';
import {
  UNITS,
  UNIT_LIST,
  convertLength,
  formatNumber,
  getAllConversions
} from './utils/converter';
import ConversionTable from './components/ConversionTable';

const PRESETS: PresetItem[] = [
  { label: '身長 (170cm)', value: 170, unitId: 'cm' },
  { label: 'A4用紙の長辺 (297mm)', value: 297, unitId: 'mm' },
  { label: '100m走 (100m)', value: 100, unitId: 'm' },
  { label: 'フルマラソン (42.195km)', value: 42.195, unitId: 'km' },
  { label: 'テレビ画面 (65in)', value: 65, unitId: 'inch' },
  { label: 'バスケゴール高さ (10ft)', value: 10, unitId: 'ft' }
];

const App = () => {
  const [inputValue, setInputValue] = useState<string>('170');
  const [fromUnit, setFromUnit] = useState<LengthUnitId>('cm');
  const [toUnit, setToUnit] = useState<LengthUnitId>('inch');
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [copiedSymbol, setCopiedSymbol] = useState<string | null>(null);

  // 入力された数値のパース
  const numericValue = useMemo(() => {
    const parsed = parseFloat(inputValue);
    return isNaN(parsed) ? 0 : parsed;
  }, [inputValue]);

  // 変換先への換算結果
  const convertedResult = useMemo(() => {
    return convertLength(numericValue, fromUnit, toUnit);
  }, [numericValue, fromUnit, toUnit]);

  // フォーマット済み結果
  const formattedResult = useMemo(() => {
    return formatNumber(convertedResult);
  }, [convertedResult]);

  // 全単位一覧用リスト
  const allConversions = useMemo(() => {
    return getAllConversions(numericValue, fromUnit);
  }, [numericValue, fromUnit]);

  // 入力値変更
  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
  };

  // 単位入れ替え
  const handleSwapUnits = () => {
    setFromUnit(toUnit);
    setToUnit(fromUnit);
  };

  // プリセット選択
  const handleSelectPreset = (preset: PresetItem) => {
    setInputValue(preset.value.toString());
    setFromUnit(preset.unitId);
  };

  // トースト表示とクリップボード書き込み
  const showToast = (message: string) => {
    setToastMessage(message);
    window.setTimeout(() => {
      setToastMessage(null);
    }, 2400);
  };

  const copyToClipboard = async (text: string, label: string) => {
    try {
      if (navigator?.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
      }
      setCopiedSymbol(label);
      showToast(`「${text}」をコピーしました`);
      window.setTimeout(() => {
        setCopiedSymbol((prev) => (prev === label ? null : prev));
      }, 2000);
    } catch {
      showToast('コピーに失敗しました');
    }
  };

  const handleCopyMainResult = () => {
    const targetSymbol = UNITS[toUnit]?.symbol ?? toUnit;
    const fullText = `${formattedResult} ${targetSymbol}`;
    copyToClipboard(fullText, 'MAIN_RESULT');
  };

  const fromUnitItem = UNITS[fromUnit];
  const toUnitItem = UNITS[toUnit];

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">
          <Ruler size={30} aria-hidden="true" />
          長さ単位変換ツール
        </h1>
        <p className="subtitle">
          mm・cm・m・km・インチ・フィートをリアルタイムに相互変換
        </p>
      </header>

      <main className="main-layout">
        <div className="converter-card">
          <div className="input-row">
            <div className="input-group">
              <label htmlFor="length-input" className="input-label">
                変換元の長さ ({fromUnitItem?.name})
              </label>
              <input
                id="length-input"
                type="number"
                step="any"
                className="number-input"
                value={inputValue}
                onChange={handleInputChange}
                placeholder="数値を入力"
              />
              <select
                id="from-unit-select"
                className="unit-select"
                value={fromUnit}
                onChange={(e) => setFromUnit(e.target.value as LengthUnitId)}
                aria-label="変換元の単位"
              >
                {UNIT_LIST.map((unit) => (
                  <option key={unit.id} value={unit.id}>
                    {unit.name} ({unit.symbol})
                  </option>
                ))}
              </select>
            </div>

            <button
              type="button"
              className="swap-btn"
              onClick={handleSwapUnits}
              title="単位を入れ替える"
              aria-label="単位を入れ替える"
            >
              <ArrowLeftRight size={20} aria-hidden="true" />
            </button>

            <div className="input-group">
              <label htmlFor="to-unit-select" className="input-label">
                変換先の単位
              </label>
              <select
                id="to-unit-select"
                className="unit-select"
                value={toUnit}
                onChange={(e) => setToUnit(e.target.value as LengthUnitId)}
              >
                {UNIT_LIST.map((unit) => (
                  <option key={unit.id} value={unit.id}>
                    {unit.name} ({unit.symbol})
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="result-display">
            <div className="result-main">
              <div>
                <span className="result-value">{formattedResult}</span>{' '}
                <span className="result-unit">{toUnitItem?.symbol}</span>
              </div>
              <button
                type="button"
                className="copy-btn"
                onClick={handleCopyMainResult}
              >
                {copiedSymbol === 'MAIN_RESULT' ? (
                  <>
                    <Check size={14} color="#16a34a" aria-hidden="true" />
                    <span>コピー完了</span>
                  </>
                ) : (
                  <>
                    <Copy size={14} aria-hidden="true" />
                    <span>結果をコピー</span>
                  </>
                )}
              </button>
            </div>
            <div className="result-meta">
              <span>
                {inputValue || 0} {fromUnitItem?.symbol} = {formattedResult}{' '}
                {toUnitItem?.symbol}
              </span>
              <span>
                基準値: {(numericValue * fromUnitItem?.toBaseMeter).toLocaleString()} m
              </span>
            </div>
          </div>

          <div className="presets-section">
            <h2 className="presets-title">
              <Sparkles size={16} aria-hidden="true" />
              日常のよくある長さプリセット
            </h2>
            <div className="preset-tags">
              {PRESETS.map((preset) => (
                <button
                  key={preset.label}
                  type="button"
                  className="preset-tag"
                  onClick={() => handleSelectPreset(preset)}
                >
                  {preset.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        <ConversionTable
          rows={allConversions}
          onCopy={copyToClipboard}
          copiedSymbol={copiedSymbol}
        />

        <p className="info-note">
          ※ 1インチは正確に 25.4mm、1フィートは 12インチ (304.8mm) として計算しています。
        </p>
      </main>

      {toastMessage && (
        <aside className="copy-toast" role="status" aria-live="polite">
          <Check size={16} aria-hidden="true" />
          <span>{toastMessage}</span>
        </aside>
      )}
    </div>
  );
};

export default App;
